-- `transaction.amount`/`capital` dulu TEXT "<KODE> <nominal>" (major unit).
-- Sekarang menyimpan instance `Money` sebagai JSON:
--   {"amount":"1500000","currency":"IDR"}
UPDATE `transaction` SET
	`amount` = json_object('amount', TRIM(SUBSTR(`amount`, INSTR(`amount`, ' ') + 1)), 'currency', SUBSTR(TRIM(`amount`), 1, 3)),
	`capital` = json_object('amount', TRIM(SUBSTR(`capital`, INSTR(`capital`, ' ') + 1)), 'currency', SUBSTR(TRIM(`capital`), 1, 3))
WHERE json_valid(`amount`) = 0;
